<script setup lang="ts">
import SelectField from '../../components/SelectField.vue'
import { computed, ref } from 'vue'
import { RefreshCw, Pause, Play, X, Info, Layers3, RotateCcw } from '@lucide/vue'
import StatusBadge from '../../components/StatusBadge.vue'
import RunDetail from './RunDetail.vue'
import { state, refresh, perform, runAction, runSource } from '../../app/state'
import { time, duration, bytes, phases } from '../../app/format'
const selectedState = ref(''); const selectedSource = ref(''); const trigger = ref(''); const detail = ref<number>(); const age = ref('')
const items = computed(()=>state.runs.filter(run=>(!selectedState.value||run.state===selectedState.value)&&(!selectedSource.value||run.source_id===selectedSource.value)&&(!trigger.value||run.trigger===trigger.value)&&(!age.value||Date.now()-new Date(run.created_at).getTime()<=Number(age.value)*86400000)))
const groups = computed(()=>{const out:Record<string,typeof items.value>={};for(const run of items.value){const day=time(run.created_at).slice(0,10);(out[day]??=[]).push(run)}return Object.entries(out)})
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">RUN TIMELINE</span><h1>批次记录<span>.</span></h1></div><button class="button" @click="perform(refresh)"><RefreshCw :size="16"/>刷新</button></div><div class="panel batch-panel"><div class="filters-grid"><label>时间范围<SelectField v-model="age" aria-label="时间范围" :options="[{ value: '', label: '最近 100 条 · 全部时间' }, { value: '1', label: '最近 24 小时' }, { value: '7', label: '最近 7 天' }]" /></label><label>同步源<SelectField v-model="selectedSource" aria-label="同步源" :options="[{ value: '', label: '全部同步源' }, ...(state.config?.config.sources ?? []).map(item => ({ value: item.id, label: item.name }))]" /></label><label>批次状态<SelectField v-model="selectedState" aria-label="批次状态" :options="[{ value: '', label: '全部状态' }, { value: 'running', label: '运行中' }, { value: 'paused', label: '已暂停' }, { value: 'succeeded', label: '成功' }, { value: 'failed', label: '失败' }, { value: 'timed_out', label: '超时' }, { value: 'interrupted', label: '中断' }]" /></label><label>运行来源<SelectField v-model="trigger" aria-label="运行来源" :options="[{ value: '', label: '全部来源' }, { value: 'manual', label: '手动触发' }, { value: 'schedule', label: '自动计划' }]" /></label></div><div class="timeline"><div v-for="[day,runs] in groups" :key="day" class="day-group"><div class="day-label"><span></span>{{day}}</div><article v-for="run in runs" :key="run.id" class="run-row" :class="{live:run.state==='running'}"><div class="run-time">{{time(run.created_at).slice(-8,-3)}}</div><div class="timeline-dot" :class="run.state"></div><div class="run-main"><div class="run-title"><strong>#{{run.id}}</strong><span class="type-pill" :class="run.type">{{run.type==='github_release'?'GitHub Release':run.type}}</span><StatusBadge :state="run.state"/><span class="run-duration">{{['running','pausing'].includes(run.state)?'已运行 ':''}}{{duration(run.elapsed_seconds)}}<span v-if="run.state==='running'"> · 剩余约 {{duration(run.progress.eta_seconds)}}</span></span></div><p class="run-subtitle">{{run.name}} · {{run.trigger==='schedule'?'自动计划':'手动触发'}} · {{phases[run.progress.phase]??run.progress.phase}}<span v-if="run.attempts.length>1"> · 已尝试 {{run.attempts.length}} 次</span></p><div v-if="run.state==='running'" class="progress-line"><div class="progress-track" :class="{indeterminate:run.progress.percent===null}"><span :style="{width:(run.progress.percent??25)+'%'}"></span></div><span>{{run.progress.percent===null?(phases[run.progress.phase]??'进行中'):`${run.type==='rsync'?'≈ ':''}${run.progress.percent.toFixed(0)}%`}}</span></div><div class="run-bottom"><div class="run-counters"><span>已传输 {{bytes(run.progress.bytes)}}</span><span v-if="run.type==='github_release'||run.progress.success>0" class="counter success">完成 {{run.progress.success}} 项</span><span v-if="run.progress.skipped" class="counter skipped">跳过 {{run.progress.skipped}}</span><span v-if="run.error_code" class="counter failed">{{run.error_code}}</span><span v-if="run.progress.speed">{{bytes(run.progress.speed)}}/s</span></div><div class="row-actions"><button v-if="['running','queued'].includes(run.state)" class="icon-button" aria-label="暂停任务" @click="perform(()=>runAction(run.id,'pause'))"><Pause :size="15"/></button><button v-if="['paused','interrupted'].includes(run.state)" class="icon-button" aria-label="继续任务" @click="perform(()=>runAction(run.id,'resume'))"><Play :size="15"/></button><button v-if="['failed','timed_out','succeeded','cancelled'].includes(run.state)" class="icon-button" aria-label="重新同步" @click="perform(()=>runSource(run.source_id))"><RotateCcw :size="15"/></button><button v-if="['queued','running','paused','interrupted','pausing'].includes(run.state)" class="icon-button" aria-label="取消任务" @click="perform(()=>runAction(run.id,'cancel'))"><X :size="15"/></button><button class="icon-button" aria-label="查看运行详情" @click="detail=run.id"><Info :size="16"/></button></div></div></div></article></div><div v-if="!items.length" class="empty-state"><Layers3 :size="32"/><h3>暂无运行批次</h3><p>从同步源页面启动任务，进度会实时出现在这里。</p></div></div></div><RunDetail v-if="detail" :id="detail" @close="detail=undefined"/></section></template>
